import pandas as pd
import sqlite3

def task_func(db_path: str, table_name: str, column_name: str) -> pd.DataFrame:
    def quote_identifier(name: str) -> str:
        if not isinstance(name, str) or name == "":
            raise ValueError("table_name and column_name must be non-empty strings")
        return '"' + name.replace('"', '""') + '"'

    if not isinstance(db_path, str) or db_path == "":
        raise ValueError("db_path must be a non-empty string")

    query = f"SELECT * FROM {quote_identifier(table_name)}"

    conn = sqlite3.connect(db_path)
    try:
        df = pd.read_sql_query(query, conn)
    finally:
        conn.close()

    if column_name not in df.columns:
        raise KeyError(f"Column {column_name!r} not found in table {table_name!r}")

    mask = df[column_name].map(lambda value: isinstance(value, str))
    df.loc[mask, column_name] = df.loc[mask, column_name].str.replace("\n", "<br>", regex=False)

    return df
